import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The claims people on each sheet make. A claim left without a date is dated the sheet's today. A claim's
 * due-by is fixed when it is added, from the terms of its person's grade in force on its date. Only a
 * DRAFT claim can be edited. No claim dated inside a closed period (not only soft-closed) can be added,
 * edited or change status; one added inside a soft-closed period is a late entry, and none can be added or edited to a date after its person's retirement date. A claim with a
 * negative amount is a correction: it is refused unless it names, by number, a SETTLED claim of the same
 * person; a claim that is not a correction names none. */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final ClaimLogRepository logs;
    private final PersonRepository people;
    private final RollupService rollup;
    private final SheetService sheets;
    private final PeriodRepository periods;
    private final SettingsService settings;
    private final PersonWatchRepository watches;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people, RollupService rollup, SheetService sheets,
            PeriodRepository periods, SettingsService settings, PersonWatchRepository watches, Audit audit) {
        this.watches = watches;
        this.claims = claims;
        this.logs = logs;
        this.people = people;
        this.rollup = rollup;
        this.sheets = sheets;
        this.periods = periods;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's claims, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
    }

    /** The status logs of the claims, by claim id, each oldest first. */
    @Transactional(readOnly = true)
    public Map<Long, List<ClaimLog>> logsOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return logs.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimLog::getClaimId));
    }

    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate dated = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, dated);
        person.requireClaimable(dated);
        refuseBadCorrection(sheetId, personId, amount, corrects);
        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects);
        claim.setDueBy(dated.plusDays(termsOf(sheetId, person, dated)));
        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
        claim.setLateEntry(periods.softClosedOn(sheetId, dated));
        claim = claims.saveAndFlush(claim);
        log(user, person, claim);
        record("CLAIM_ADDED", user, person, claim, claim.getNumber());
        if (claim.isLateEntry()) record("LATE_ENTRY", user, person, claim, claim.getNumber());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    @Transactional
    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
        LocalDate dated = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, claim.getDate());
        refuseClosed(sheetId, dated);
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        person.requireClaimable(dated);
        refuseBadCorrection(sheetId, person.getId(), amount, corrects);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setAmount(amount);
        claim.setCorrects(corrects);
        claim.setDate(dated);
        claim.setNote(noteOf(note));
        claim.unlock();
        claims.flush();
        record("CLAIM_EDITED", user, person, claim, claim.getNumber());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }
package net.officefloor.hq.app.quickadd;

import java.math.BigDecimal;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Adds a DRAFT claim, dated the sheet's today with an empty note, for a person named on the sheet,
 * first adding them with grade A when no one has that name. It is one change: when the claim is
 * refused the person is not added either, and nothing is recorded. */
@Service
public class QuickAddService {

    /** The grade a person added by a quick-add is given. */
    static final String GRADE = "A";

    public record Added(Person person, Claim claim) {
    }

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService) {
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
    }

    @Transactional
    public Added add(String sheetId, String user, String name, BigDecimal amount) {
        Person person = people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
                .orElseGet(() -> personService.add(sheetId, user, name, GRADE, null));
        Claim claim = claimService.add(sheetId, user, person.getId(), amount, null, "", null);
        return new Added(person, claim);
    }
}
import org.springframework.transaction.annotation.Transactional;

/** Adds a DRAFT claim per pasted line of {@code name,amount,date,note}, in order, for the person on the
 * sheet with that name (compared as names are). The date may be blank (the sheet's today); the note may
 * hold commas, or be left out. Each line is held to the claim form's rules; it is one change: when any
 * line is refused no claim is added, and nothing is recorded. Blank lines are skipped. */
@Service
public class PasteService {

    /** An amount as the claim form takes it. */
    private static final Pattern AMOUNT = Pattern.compile("\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*");

    /** The longest note the claim form takes. */
    private static final int NOTE_MAX = 500;

    private final PersonRepository people;
    private final ClaimService claimService;

    public PasteService(PersonRepository people, ClaimService claimService) {
        this.people = people;
        this.claimService = claimService;
    }

    /** The claims added, in the order of their lines. */
    @Transactional
    public List<Claim> paste(String sheetId, String user, String text) {
        List<Claim> added = new ArrayList<>();
        for (String line : text.split("\\r?\\n")) {
            if (line.isBlank()) continue;
            String[] fields = line.split(",", 4);
            if (fields.length < 2 || fields[0].isBlank() || !AMOUNT.matcher(fields[1]).matches()) {
                throw new PasteLineException();
            }
            Person person = people.findBySheetIdAndNameKey(sheetId, Person.keyOf(fields[0]))
                    .orElseThrow(PersonNotFoundException::new);
            String note = fields.length > 3 ? fields[3].trim() : "";
            if (note.length() > NOTE_MAX) throw new PasteLineException();
            BigDecimal amount = new BigDecimal(fields[1].trim()).setScale(2);
            added.add(claimService.add(sheetId, user, person.getId(), amount, dateOf(fields), note, null));
        }
        if (added.isEmpty()) throw new PasteLineException();
        return added;
    }

    /** The line's date; null when it is blank or left out. */
    private static LocalDate dateOf(String[] fields) {
        if (fields.length < 3 || fields[2].isBlank()) return null;
        try {
            return LocalDate.parse(fields[2].trim());
        } catch (DateTimeParseException e) {
            throw new PasteLineException();
        }
    }
}

